ALTER TABLE "finance_day_closings" DROP CONSTRAINT "finance_day_closings_net_check";--> statement-breakpoint
ALTER TABLE "finance_day_closings" ADD COLUMN "supplier_paid_count" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "finance_day_closings" ADD COLUMN "supplier_paid_cents" bigint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "finance_day_closings" ADD CONSTRAINT "finance_day_closings_net_check" CHECK ("finance_day_closings"."net_cents" = "finance_day_closings"."collected_cents" - "finance_day_closings"."reversed_cents" - "finance_day_closings"."refund_paid_cents" - "finance_day_closings"."supplier_paid_cents");--> statement-breakpoint
COMMENT ON COLUMN "finance_day_closings"."supplier_paid_count" IS 'O gün ödeme tarihli, iptal edilmemiş nakit tedarikçi ödemesi adedi (DOM-FIN-076, K-166); nakit yönteminde sayılır. Bu kolondan önceki kapanışlarda 0.';--> statement-breakpoint
COMMENT ON COLUMN "finance_day_closings"."supplier_paid_cents" IS 'O gün kasadan ödenen tedarikçi ödemelerinin toplamı (kuruş); netten ve kasa beklenenden düşer. Bu kolondan önceki kapanışlarda 0.';--> statement-breakpoint
COMMENT ON COLUMN "finance_day_closings"."net_cents" IS 'Tahsilat eksi iptal eksi iade ödemesi eksi nakit tedarikçi ödemesi (kuruş); kısıtla eşitlenir.';--> statement-breakpoint
COMMENT ON COLUMN "finance_day_closings"."expected_cash_cents" IS 'Açılış artı günün net nakdi (kuruş); iptal edilen nakit ve nakit tedarikçi ödemesi kasadan çıkmış sayılır, eksi olabilir.';--> statement-breakpoint
COMMENT ON COLUMN "finance_day_closings"."method_totals" IS 'Yöntem bazında özet: payments.method anahtarı, tahsilat, iptal, iade ödemesi ve tedarikçi ödemesi adedi ile kuruş tutarı, net. İade alanları yalnız banka havalesi, tedarikçi alanları yalnız nakit satırında dolar; 0083 (iade) ve 0086 (tedarikçi) öncesi satırlarda yoktur, 0 okunur.';--> statement-breakpoint
COMMENT ON TABLE "supplier_payments" IS 'Tedarikçi ödemesi (DOM-FIN-076): bir taksite yazılır, kısmi olabilir; taksitin kalanını aşamaz (kurum kilidi altında denetlenir). Nakit dışı ödeme kurumun bildirilmiş banka hesabından çıkar (DOM-FIN-032). Nakit ödeme ödeme gününün gün sonuna nakit yönteminde girer ve kasa beklenenini düşürür; kapatılmış güne yazılmaz, ödeme günü kapatılmışsa iptal edilmez (DOM-FIN-036, K-166, K-190). Silinmez, gerekçeyle iptal edilir; iptal edilen nakit ödeme ödeme gününün gün sonundan çıkar. Havale ve EFT ödemeleri genel talimat dosyasına alınır (K-164).';
